#define _POSIX_C_SOURCE 200809L

#include "hunmin_state.h"

#include <stdlib.h>
#include <string.h>

/* One page of the IBus panel's lookup table. IBus's own default label list is
 * 1..9 (src/ibuslookuptable.c, labels are generated by the panel), so a page of
 * nine is what a panel can number without us supplying labels. This is a
 * HOST ceiling like fcitx5's ten (frontends/fcitx5/src/hunminadapter.cpp,
 * kMaxCandidatePageSize), not a preference -- the candidate-window gate is
 * tier D3's job (issue #292), and it is where a different number gets measured. */
#define HUNMIN_CANDIDATE_PAGE_SIZE 9

struct hunmin_state {
    hunmin_ctx *ctx;
    hunmin_buffered_preedit *layer;

    char *hangul_id; /* owned; what the caller asked for */
    char *latin_id;  /* owned or NULL */
    int policy;      /* HUNMIN_COMMIT_*, the policy layer was built with */
    int caps;
    int autoswitch_want; /* what the frontend asked for; re-applied per layer */
    int autoswitch_held; /* what the engine accepted (B3 can refuse ON) */

    hunmin_state_sink sink;

    /* The candidate list. Owned copies: the engine's ctx answers are borrowed
     * until its next hunmin_suggest_* call, and the list must survive the
     * key that closes it. */
    char **cand_text;
    char **cand_detail;
    int cand_count;
    int cand_cursor;
};

/* ------------------------------------------------------------------ helpers */

static char *dup_or_empty(const char *s) {
    if (!s) s = "";
    size_t n = strlen(s) + 1;
    char *p = malloc(n);
    if (p) memcpy(p, s, n);
    return p;
}

static void emit_commit(hunmin_state *s, const char *text) {
    if (!text || !*text) return;
    if (s->sink.commit) s->sink.commit(s->sink.user, text);
}

static void emit_preedit(hunmin_state *s) {
    if (!s->sink.preedit) return;
    const char *shown = s->layer ? hunmin_buffered_preedit_display(s->layer) : "";
    if (!shown) shown = "";
    /* IBus counts the cursor in characters, not bytes (ibus_engine_update_
     * preedit_text takes a guint cursor_pos over the text's characters). The
     * conversion belongs here, once, so neither host re-derives it. */
    int chars = 0;
    for (const unsigned char *p = (const unsigned char *)shown; *p; ++p)
        if ((*p & 0xC0) != 0x80) ++chars;
    s->sink.preedit(s->sink.user, shown, chars);
}

static void candidates_clear(hunmin_state *s) {
    for (int i = 0; i < s->cand_count; ++i) {
        free(s->cand_text[i]);
        free(s->cand_detail[i]);
    }
    free(s->cand_text);
    free(s->cand_detail);
    s->cand_text = NULL;
    s->cand_detail = NULL;
    s->cand_count = 0;
    s->cand_cursor = 0;
}

static void candidates_notify(hunmin_state *s, int open) {
    if (s->sink.candidates) s->sink.candidates(s->sink.user, open);
}

static void candidates_close(hunmin_state *s) {
    if (s->cand_count == 0) return;
    candidates_clear(s);
    candidates_notify(s, 0);
}

/* Close the open list because the next key is not one of its keys: the same
 * rule fcitx5's adapter applies, and it happens before the key is fed so the
 * key still composes. */
static void candidates_close_if_open(hunmin_state *s) {
    if (s->cand_count > 0) candidates_close(s);
}

static void layer_free(hunmin_state *s) {
    if (!s->layer) return;
    hunmin_buffered_preedit_free(s->layer);
    s->layer = NULL;
}

/* Build the layer, or keep the live one. A rebuild delivers the old word first:
 * a layout or policy change is a focus-like boundary, and dropping the
 * composition silently is how a character reaches neither the client nor the
 * screen.
 *
 * The layout id is not compared here on purpose: layout_id() reports the
 * ACTIVE language, so in Latin mode it legitimately differs from the Hangul id
 * this state was configured with. The two calls that can change the ids
 * (hunmin_state_set_layouts, hunmin_state_set_commit_policy) free the layer
 * themselves, so a different id under the same policy means "the layer is in
 * the other language", not "rebuild". */
static bool ensure_layer(hunmin_state *s) {
    if (!s->ctx) return false;
    if (s->layer) {
        if (hunmin_buffered_preedit_commit_policy(s->layer) == s->policy) return true;
        emit_commit(s, hunmin_buffered_preedit_commit_word(s->layer));
        layer_free(s);
    }
    const char *hangul = s->hangul_id ? s->hangul_id : "dubeolsik";
    s->layer = hunmin_buffered_preedit_new(s->ctx, hangul, s->latin_id, s->policy);
    if (!s->layer) return false;
    hunmin_buffered_preedit_set_option(s->layer, "caps", s->caps);
    /* ReqMode8's `english_valid` reads this list. Absent data is a normal state
     * (B3) and the judgement abstains; it is not an error. */
    hunmin_buffered_preedit_load_english_shipped(s->layer);
    /* The preference belongs to the person, not to the layer: a rebuilt layer
     * starts at the engine default OFF, so the requested value is re-applied
     * and what the engine holds is read back. */
    s->autoswitch_held = s->autoswitch_want;
    hunmin_buffered_preedit_set_option(s->layer, "autoswitch", s->autoswitch_want);
    if (!hunmin_buffered_preedit_get_option(s->layer, "autoswitch", &s->autoswitch_held))
        s->autoswitch_held = 0;
    return true;
}

/* ------------------------------------------------------------------- public */

hunmin_state *hunmin_state_new(const char *const *dirs, int ndirs) {
    hunmin_state *s = calloc(1, sizeof *s);
    if (!s) return NULL;
    s->ctx = hunmin_ctx_new(dirs, ndirs);
    if (!s->ctx) {
        free(s);
        return NULL;
    }
    s->hangul_id = dup_or_empty("dubeolsik");
    s->latin_id = dup_or_empty("us-qwerty");
    s->policy = HUNMIN_COMMIT_AT_BOUNDARY;
    if (!s->hangul_id || !s->latin_id) {
        hunmin_state_free(s);
        return NULL;
    }
    return s;
}

void hunmin_state_free(hunmin_state *s) {
    if (!s) return;
    candidates_clear(s);
    layer_free(s);
    free(s->hangul_id);
    free(s->latin_id);
    if (s->ctx) hunmin_ctx_free(s->ctx);
    free(s);
}

void hunmin_state_set_sink(hunmin_state *s, const hunmin_state_sink *sink) {
    if (!s) return;
    if (sink) s->sink = *sink;
    else memset(&s->sink, 0, sizeof s->sink);
}

bool hunmin_state_set_layouts(hunmin_state *s, const char *hangul_id, const char *latin_id) {
    if (!s || !hangul_id || !*hangul_id) return false;
    char *h = dup_or_empty(hangul_id);
    char *l = latin_id && *latin_id ? dup_or_empty(latin_id) : NULL;
    if (!h) {
        free(l);
        return false;
    }
    if (s->layer) {
        emit_commit(s, hunmin_buffered_preedit_commit_word(s->layer));
        layer_free(s);
    }
    candidates_close(s);
    free(s->hangul_id);
    free(s->latin_id);
    s->hangul_id = h;
    s->latin_id = l;
    const bool ok = ensure_layer(s);
    emit_preedit(s);
    return ok;
}

bool hunmin_state_set_commit_policy(hunmin_state *s, int policy) {
    if (!s) return false;
    if (policy != HUNMIN_COMMIT_PER_SYLLABLE) policy = HUNMIN_COMMIT_AT_BOUNDARY;
    if (s->policy == policy) return true;
    s->policy = policy;
    if (!s->layer) return true;
    /* Same reason as a layout change: deliver what was composing under the old
     * policy, then build the new one. */
    emit_commit(s, hunmin_buffered_preedit_commit_word(s->layer));
    layer_free(s);
    const bool ok = ensure_layer(s);
    emit_preedit(s);
    return ok;
}

int hunmin_state_set_language(hunmin_state *s, int language) {
    if (!s) return language == HUNMIN_LANGUAGE_LATIN ? HUNMIN_LANGUAGE_LATIN
                                                     : HUNMIN_LANGUAGE_HANGUL;
    if (!ensure_layer(s)) return hunmin_state_language(s);
    if (hunmin_buffered_preedit_language(s->layer) == language) return language;
    hunmin_key_result out = {0};
    if (!hunmin_buffered_preedit_toggle_language(s->layer, &out)) return hunmin_state_language(s);
    emit_commit(s, out.commit);
    emit_preedit(s);
    return hunmin_buffered_preedit_language(s->layer);
}

int hunmin_state_set_autoswitch(hunmin_state *s, int want) {
    if (!s) return want ? 1 : 0;
    s->autoswitch_want = want ? 1 : 0;
    /* The option lives on a layer, and a settings surface may be the first
     * thing that runs (before any key). Build it here rather than answering
     * for a layer that does not exist yet. */
    if (!ensure_layer(s)) return 0;
    hunmin_buffered_preedit_set_option(s->layer, "autoswitch", s->autoswitch_want);
    s->autoswitch_held = s->autoswitch_want;
    if (!hunmin_buffered_preedit_get_option(s->layer, "autoswitch", &s->autoswitch_held))
        s->autoswitch_held = 0;
    return s->autoswitch_held;
}

bool hunmin_state_get_autoswitch(const hunmin_state *s, int *out) {
    if (!s || !s->layer) return false;
    return hunmin_buffered_preedit_get_option(s->layer, "autoswitch", out);
}

bool hunmin_state_autoswitch_data_present(const hunmin_state *s) {
    return s && s->ctx && hunmin_ctx_autoswitch_data_present(s->ctx);
}

void hunmin_state_set_caps(hunmin_state *s, int on) {
    if (!s) return;
    s->caps = on ? 1 : 0;
    if (s->layer) hunmin_buffered_preedit_set_option(s->layer, "caps", s->caps);
}

/* ReqMode8/ReqMode10's judgement: the finished word is already delivered in the
 * judged language; this performs the MODE half. Returns the boundary text the
 * switch itself delivered, so the caller keeps one commit point per key. */
static void apply_judgement(hunmin_state *s, char **switched_out) {
    *switched_out = NULL;
    if (!s->layer) return;
    const int judged = hunmin_buffered_preedit_take_judgement(s->layer);
    if (judged < 0 || judged == hunmin_buffered_preedit_language(s->layer)) return;
    hunmin_key_result out = {0};
    if (!hunmin_buffered_preedit_toggle_language(s->layer, &out)) return;
    /* out.commit is borrowed until the next engine call; copy it now. */
    *switched_out = dup_or_empty(out.commit);
}

static int handle_candidate_key(hunmin_state *s, const hunmin_key_event *ev) {
    switch (ev->id) {
    case HUNMIN_KEY_ESCAPE:
        candidates_close(s);
        return 1;
    case HUNMIN_KEY_ENTER:
        /* Commit whatever the cursor is on. The cursor starts at 0, the
         * highest-frequency candidate, so a plain Return after the open key
         * picks the best match -- the common case, the same rule fcitx5's
         * adapter applies. */
        hunmin_state_candidate_commit(s, s->cand_cursor);
        return 1;
    case HUNMIN_KEY_UP:
    case HUNMIN_KEY_LEFT:
        if (s->cand_count > 0)
            s->cand_cursor = (s->cand_cursor + s->cand_count - 1) % s->cand_count;
        candidates_notify(s, 1);
        return 1;
    case HUNMIN_KEY_DOWN:
    case HUNMIN_KEY_RIGHT:
        if (s->cand_count > 0) s->cand_cursor = (s->cand_cursor + 1) % s->cand_count;
        candidates_notify(s, 1);
        return 1;
    case HUNMIN_KEY_PAGE_UP: {
        int target = s->cand_cursor - HUNMIN_CANDIDATE_PAGE_SIZE;
        s->cand_cursor = target > 0 ? target : 0;
        candidates_notify(s, 1);
        return 1;
    }
    case HUNMIN_KEY_PAGE_DOWN: {
        int target = s->cand_cursor + HUNMIN_CANDIDATE_PAGE_SIZE;
        int last = s->cand_count > 0 ? s->cand_count - 1 : 0;
        s->cand_cursor = target < last ? target : last;
        candidates_notify(s, 1);
        return 1;
    }
    default:
        return 1;
    }
}

int hunmin_state_key(hunmin_state *s, const hunmin_key_event *ev) {
    if (!s || !ev) return 0;
    if (!ensure_layer(s)) return 0;

    const hunmin_key_action action = hunmin_buffered_preedit_classify(s->layer, ev);

    if (action == HUNMIN_KEY_LANGUAGE_TOGGLE) {
        hunmin_key_result out = {0};
        const int toggled = hunmin_buffered_preedit_toggle_language(s->layer, &out);
        if (toggled) {
            /* The toggle's own boundary is delivered here, and the key is ours:
             * the host gave us the trigger, we answered it. A single-language
             * layer answers 0 and the key reaches the client. */
            emit_commit(s, out.commit);
            emit_preedit(s);
            return 1;
        }
        emit_commit(s, out.commit);
        emit_preedit(s);
        return 0;
    }
    if (action == HUNMIN_KEY_LANGUAGE_CHORD) {
        /* No function is bound on this frontend yet (voice, the autoswitch
         * chord): the binding table ships empty, so classify() only answers
         * this for a chord someone seeded. Treat it as the plain toggle rather
         * than a dead key, which is the rule an unbound chord already gets. */
        hunmin_key_result out = {0};
        const int toggled = hunmin_buffered_preedit_toggle_language(s->layer, &out);
        emit_commit(s, out.commit);
        emit_preedit(s);
        return toggled;
    }
    if (action == HUNMIN_KEY_CANDIDATE) return handle_candidate_key(s, ev);
    if (action == HUNMIN_KEY_BOUNDARY_PASS) {
        candidates_close_if_open(s);
        /* The key belongs to the client; the word in flight does not. */
        emit_commit(s, hunmin_buffered_preedit_commit_word(s->layer));
        emit_preedit(s);
        return 0;
    }

    /* HUNMIN_KEY_FEED. Any other key closes an open window and falls through,
     * so typing continues where the user left off instead of being swallowed
     * by an invisible window. */
    candidates_close_if_open(s);

    hunmin_buffered_preedit_set_option(s->layer, "caps", s->caps);
    hunmin_key_result out = {0};
    const int used = hunmin_buffered_preedit_process_key(s->layer, ev->base, ev->shift, &out) != 0;
    /* Both strings are borrowed until the next hunmin_* call, and the judgement
     * below makes several. Copy first: on a boundary key that both delivers a
     * word and switches language, reading out.commit afterwards yields "". */
    char *delivered = dup_or_empty(out.commit);
    char *switched = NULL;
    apply_judgement(s, &switched);
    if (delivered && *delivered) emit_commit(s, delivered);
    if (switched && *switched) emit_commit(s, switched);
    free(delivered);
    free(switched);
    emit_preedit(s);
    /* Only what the layer took is consumed; a declined key belongs to the
     * client (docs/DESIGN-FRONTEND.md Part B §5 rule 3). */
    return used;
}

int hunmin_state_toggle_candidates(hunmin_state *s) {
    if (!s) return 0;
    if (s->cand_count > 0) {
        candidates_close(s);
        return 1;
    }
    if (!ensure_layer(s)) return 0;
    const char *shown = hunmin_buffered_preedit_display(s->layer);
    if (!shown || !*shown) return 0;
    const int n = hunmin_suggest_count(s->ctx, shown);
    if (n <= 0) return 0;
    char **texts = calloc((size_t)n, sizeof *texts);
    char **details = calloc((size_t)n, sizeof *details);
    if (!texts || !details) {
        free(texts);
        free(details);
        return 0;
    }
    int kept = 0;
    for (int i = 0; i < n; ++i) {
        const char *t = hunmin_suggest_text(s->ctx, i);
        if (!t || !*t) continue;
        texts[kept] = dup_or_empty(t);
        details[kept] = dup_or_empty(hunmin_suggest_detail(s->ctx, i));
        if (!texts[kept] || !details[kept]) {
            free(texts[kept]);
            free(details[kept]);
            break;
        }
        ++kept;
    }
    if (kept == 0) {
        for (int i = 0; i < n; ++i) {
            free(texts[i]);
            free(details[i]);
        }
        free(texts);
        free(details);
        return 0;
    }
    s->cand_text = texts;
    s->cand_detail = details;
    s->cand_count = kept;
    s->cand_cursor = 0;
    candidates_notify(s, 1);
    return 1;
}

void hunmin_state_flush(hunmin_state *s) {
    if (!s || !s->layer) return;
    candidates_close(s);
    emit_commit(s, hunmin_buffered_preedit_commit_word(s->layer));
    emit_preedit(s);
}

void hunmin_state_reset(hunmin_state *s) {
    if (!s) return;
    candidates_close(s);
    if (s->layer) hunmin_buffered_preedit_reset(s->layer);
    emit_preedit(s);
}

int hunmin_state_candidates_open(const hunmin_state *s) { return s && s->cand_count > 0; }

int hunmin_state_candidate_commit(hunmin_state *s, int i) {
    if (!s || i < 0 || i >= s->cand_count) return 0;
    char *chosen = dup_or_empty(s->cand_text[i]);
    if (!chosen) return 0;
    if (s->layer) hunmin_buffered_preedit_reset(s->layer);
    candidates_clear(s);
    candidates_notify(s, 0);
    emit_commit(s, chosen);
    free(chosen);
    emit_preedit(s);
    return 1;
}

int hunmin_state_candidate_count(const hunmin_state *s) { return s ? s->cand_count : 0; }

const char *hunmin_state_candidate_text(const hunmin_state *s, int i) {
    if (!s || i < 0 || i >= s->cand_count) return "";
    return s->cand_text[i];
}

const char *hunmin_state_candidate_detail(const hunmin_state *s, int i) {
    if (!s || i < 0 || i >= s->cand_count) return "";
    return s->cand_detail[i];
}

int hunmin_state_candidate_cursor(const hunmin_state *s) { return s ? s->cand_cursor : 0; }

int hunmin_state_language(const hunmin_state *s) {
    return s && s->layer ? hunmin_buffered_preedit_language(s->layer) : HUNMIN_LANGUAGE_HANGUL;
}

const char *hunmin_state_layout_id(const hunmin_state *s) {
    return s && s->layer ? hunmin_buffered_preedit_layout_id(s->layer) : "";
}

const char *hunmin_state_preedit(const hunmin_state *s) {
    if (!s || !s->layer) return "";
    const char *shown = hunmin_buffered_preedit_display(s->layer);
    return shown ? shown : "";
}